const state={data:null,projectId:null,taskId:null,folder:null,chatsExpanded:false,sessionSnapshot:null};
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
async function api(url,method='GET',body){
 if(method!=='GET'&&state.data?.api_version!==9)throw Error('Restart the local server with python3 app.py, then reload this page.');
 const options={method,headers:{}};
 if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}
 const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data;
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function current(){return state.data?.projects.find(project=>project.id===state.projectId)}
function taskById(id=state.taskId){return current()?.tasks.find(task=>task.id===id)}
function harnessName(key){return state.data?.harnesses.find(harness=>harness.key===key)?.label||key||'Harness'}
function taskPresentation(text){
 const raw=String(text||'').replace(/\s+/g,' ').trim();const link=raw.match(/\[([^\]]+)\]\([^)]*\)/);const withoutLinks=raw.replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/(?:\s*\(?\/?(?:Users|home)\/[^)\s]+\)?)/g,'').trim();
 let title=withoutLinks.replace(/^i want to\s+/i,'').replace(/\s+here\s*:\s*[^:]+$/i,'').replace(/\s+here\s*:?\s*$/i,'').replace(/\s*:\s*$/,'').trim();
 if(!title)title=link?.[1]||'Untitled task';title=title.charAt(0).toUpperCase()+title.slice(1);
 return {title:title.length>72?title.slice(0,69)+'…':title,source:link?.[1]||null};
}
function harnessStatus(harness){return harness.availability||{label:'Unknown',reason:'Scan harnesses to check availability.'}}
function modelOptions(key,selected='default'){const models=[...new Set([...(state.data.adapters[key]?.models||['default']),selected].filter(Boolean))];return models.map(model=>'<option value="'+esc(model)+'" '+(model===selected?'selected':'')+'>'+esc(model==='default'?'Harness default':model)+'</option>').join('')}

async function load(){
 const fresh=await api('/api/bootstrap');const changed=JSON.stringify(fresh)!==JSON.stringify(state.data);state.data=fresh;
 if(!current())state.projectId=fresh.projects[0]?.id||null;
 if(changed)render();if(state.taskId)await refreshSession();
}
function render(){
 const project=current();
 $('#project-name').textContent=project?.name||'Your workspace';$('#project-path').textContent=project?.repo_path||'';
 $('#new-goal').disabled=!project;$('#workspace-settings').disabled=!project;
 $('#welcome').classList.toggle('hidden',!!state.taskId);$('#goal-view').classList.toggle('hidden',!state.taskId);
 renderProjectBoard(project);
 renderTree();
}
function boardColumn(task){const run=task.run_status||task.run?.status; if(task.status==='completed'||run==='complete')return 'done';if(['awaiting_review','awaiting_commit'].includes(run))return 'review';if(['queued','running','verifying','rotating','committing','awaiting_dispatch','awaiting_resume','paused_cooldown','awaiting_external_auth'].includes(run))return 'running';return 'planned'}
function targetBadge(task){const remote=task.execution_backend==='coder';return '<span class="execution-badge '+(remote?'remote':'')+'">'+(remote?'◌ Coder · ':'⌂ ')+esc(task.execution_target_label||'Local')+'</span>'}
function renderProjectBoard(project){
 const host=$('#welcome');if(!project){host.innerHTML='<div class="welcome-mark">↗</div><h1>What do you want to build?</h1><p>Add a local project, then create a task. Rotation keeps the discussion, progress, and handoffs together.</p><button id="welcome-add">Add your first project</button>';$('#welcome-add').onclick=openProjectForm;return}
 const columns=[['planned','Planned'],['running','Running'],['review','Needs review'],['done','Done']];
 host.innerHTML='<div class="board-heading"><div><span class="eyebrow">PROJECT TASKS</span><h1>'+esc(project.name)+'</h1><p>'+esc(project.coder_profile?.enabled?'Tasks can use local execution or the connected Coder environment.':'Tasks run locally until this project connects to Coder.')+'</p></div><button id="welcome-add">New task</button></div><div class="task-board">'+columns.map(([key,label])=>{const tasks=project.tasks.filter(task=>boardColumn(task)===key);return '<section class="board-column"><header><h2>'+label+'</h2><span>'+tasks.length+'</span></header><div class="board-cards">'+(tasks.length?tasks.map(task=>'<button class="board-card" data-board-task="'+task.id+'"><strong>'+esc(taskPresentation(task.text).title)+'</strong>'+targetBadge(task)+'<small>'+esc(task.run?.message||(task.run?phaseLabel(task.run.status):'Ready'))+'</small></button>').join(''):'<p class="board-empty">No tasks</p>')+'</div></section>'}).join('')+'</div>';
 $('#welcome-add').onclick=newTask;host.querySelectorAll('[data-board-task]').forEach(button=>button.onclick=()=>openSession(+button.dataset.boardTask));
}
function renderTree(){
 const hasHidden=state.data.projects.some(project=>project.tasks.length>5);
 $('#toggle-chats').hidden=!hasHidden;$('#toggle-chats').textContent=state.chatsExpanded?'Show fewer':'Show all';
 $('#project-tree').innerHTML=state.data.projects.map(project=>{
  const active=project.id===state.projectId, tasks=project.tasks, selected=tasks.find(task=>task.id===state.taskId);
  let visible=state.chatsExpanded?tasks:tasks.slice(0,5);
  if(selected&&!visible.includes(selected))visible=[...visible.slice(0,4),selected];
  return '<section class="project-group"><button class="project-button '+(active?'selected':'')+'" data-project="'+project.id+'"><span>▱ '+esc(project.name)+'</span><small>'+tasks.length+'</small></button>'+visible.map((task,index)=>{
   const position=tasks.indexOf(task);return '<div class="chat-row '+(task.id===state.taskId?'active':'')+'"><button class="tree-task" data-task="'+task.id+'" data-owner="'+project.id+'"><span>'+esc(task.text)+'</span></button><div class="chat-actions"><button data-rename="'+task.id+'" aria-label="Rename task">···</button><button data-task-move="'+task.id+'" data-owner="'+project.id+'" data-step="-1" '+(position===0?'disabled':'')+' aria-label="Move task up">↑</button><button data-task-move="'+task.id+'" data-owner="'+project.id+'" data-step="1" '+(position===tasks.length-1?'disabled':'')+' aria-label="Move task down">↓</button></div></div>';
  }).join('')+(tasks.length>5&&!state.chatsExpanded?'<p class="tree-empty">'+(tasks.length-5)+' more chat'+(tasks.length-5===1?'':'s')+'</p>':'')+(tasks.length?'':'<p class="tree-empty">No chats yet</p>')+'</section>';
 }).join('')||'<p class="tree-empty">Add a folder to get started.</p>';
 document.querySelectorAll('[data-project]').forEach(button=>button.onclick=()=>{state.projectId=+button.dataset.project;state.taskId=null;state.sessionSnapshot=null;render()});
 document.querySelectorAll('[data-task]').forEach(button=>button.onclick=()=>{state.projectId=+button.dataset.owner;openSession(+button.dataset.task)});
 document.querySelectorAll('[data-rename]').forEach(button=>button.onclick=()=>renameTask(+button.dataset.rename));
 document.querySelectorAll('[data-task-move]').forEach(button=>button.onclick=()=>moveTask(+button.dataset.owner,+button.dataset.taskMove,+button.dataset.step));
}
$('#toggle-chats').onclick=()=>{state.chatsExpanded=!state.chatsExpanded;renderTree()};

async function openSession(id){state.taskId=id;state.sessionSnapshot=null;state.followOutput=true;render();await refreshSession()}
function phaseLabel(status){return ({running:'Working',verifying:'Checking results',awaiting_dispatch:'Ready to start',awaiting_review:'Ready for review',awaiting_commit:'Ready to finish',awaiting_resume:'Handoff paused',awaiting_external_auth:'Connect GitHub',rotating:'Switching harnesses',queued:'Starting',committing:'Finishing',paused_cooldown:'Waiting for availability',complete:'Completed',stopped:'Needs attention',discarded:'Closed'})[status]||String(status||'').replaceAll('_',' ')}
function attemptStatus(attempt,attempts=[]){if(attempt.display_status)return attempt.display_status;if(attempt.status==='quota'){const next=attempts.find(item=>item.id>attempt.id&&item.run_id===attempt.run_id);return 'Usage limit reached'+(next?' · handed to '+harnessName(next.harness_key):'')}return ({running:'Working',verified:'Ready for review',completed:'Finished',failed:'Needs attention',verify_failed:'Checks need attention',discarded:'Closed',interrupted:'Interrupted',merge_failed:'Merge needs attention'})[attempt.status]||phaseLabel(attempt.status)}
async function refreshSession(){
 const id=state.taskId;if(!id)return;const data=await api('/api/tasks/'+id);if(state.taskId!==id)return;state.sessionData=data;
 const snapshot=JSON.stringify(data);const latest=data.run;const isActive=latest&&!['complete','stopped','discarded','blocked'].includes(latest.status);
 if(state.sessionSnapshot===snapshot){if(isActive&&latest.attempt_id){const output=await api('/api/attempts/'+latest.attempt_id+'/log');if(state.taskId===id)renderActivity(output)}return}
 state.sessionSnapshot=snapshot;const presentation=taskPresentation(data.task.text);$('#goal-title').textContent=presentation.title;$('#goal-title').title=data.task.text;
 const attempt=data.attempts.find(item=>item.id===latest?.attempt_id);const owner=isActive&&attempt?{label:harnessName(attempt.harness_key),model:attempt.model}:data.next_harness;
 $('#task-context').textContent=owner?(isActive?'Working with ':'Next: ')+owner.label+(owner.model&&owner.model!=='default'?' · '+owner.model:'')+(presentation.source?' · source: '+presentation.source:''):presentation.source?'Source: '+presentation.source:'';
 renderPullRequests(data.pull_requests||[]);
 $('#goal-status').textContent=isActive?(owner?owner.label+' · ':'')+phaseLabel(latest.status):(data.task.status==='completed'?'Ready for a follow-up':'Ready');
 $('#run-session').disabled=!!isActive||data.task.status==='completed';$('#message-text').disabled=!!isActive;$('#send-message').disabled=!!isActive;
 renderRunBanner(data,attempt,isActive);renderConversation(data);hydrateHarnessProgress(data);
 if(isActive&&latest.attempt_id&&['running','verifying'].includes(latest.status)){const output=await api('/api/attempts/'+latest.attempt_id+'/log');if(state.taskId===id)renderActivity(output)}else{$('#run-activity').hidden=true;renderNativeSession(null)}
 followLatest();
}
function pullRequestLabel(pr){const state=({untracked:'Linked',draft:'Draft',open:'Open',merged:'Merged',closed:'Closed'})[pr.state]||'Linked';const review=({approved:'Approved',changes_requested:'Changes requested',pending:'Review pending'})[pr.review_state];return state+(review?' · '+review:'')}
function renderPullRequests(pullRequests){const host=$('#pull-requests');if(!host)return;if(!pullRequests.length){host.innerHTML='<button id="link-pull-request" class="secondary" type="button">Link PR</button>';const link=$('#link-pull-request');if(link)link.onclick=async()=>{const url=prompt('GitHub pull-request URL');if(!url?.trim())return;try{await api('/api/tasks/'+state.taskId+'/pull-requests','POST',{url:url.trim()});state.sessionSnapshot=null;await load();toast('Pull request linked')}catch(error){toast(error.message)}};return}host.innerHTML='<div class="pull-request-list">'+pullRequests.map(pr=>'<a class="pull-request" href="'+esc(pr.url)+'" target="_blank" rel="noopener noreferrer"><span>PR #'+esc(pr.number||'…')+'</span><small>'+esc(pullRequestLabel(pr))+'</small></a>').join('')+'<button id="sync-pull-requests" class="secondary" type="button">Sync PR</button></div>';const sync=$('#sync-pull-requests');if(sync)sync.onclick=async()=>{sync.disabled=true;try{await api('/api/tasks/'+state.taskId+'/pull-requests/sync','POST',{});state.sessionSnapshot=null;await load();toast('Pull-request status refreshed')}catch(error){toast(error.message)}finally{sync.disabled=false}}}
function renderRunBanner(data,attempt,isActive){
 const run=data.run;let html='';
 if(run&&run.status!=='complete'){
  const connection=data.connection_action;
  html='<section class="run-notice"><div><strong>'+esc(attempt?.display_status||phaseLabel(run.status))+'</strong><p>'+esc(conciseRunMessage(attempt?.display_reason||run.message||''))+'</p></div><div class="actions">'+
   (connection?'<button id="connect-run-account">Connect account</button><button data-action="resume-after-auth">Check connection and continue</button>':'')+
   (run.status==='awaiting_dispatch'?'<button data-action="approve-dispatch">Start harness</button>':'')+
   (run.status==='awaiting_review'?'<button data-action="complete">'+(data.lease?.backend==='coder'?'Commit, push & create PR':'Finish')+'</button>':run.status==='awaiting_commit'?'<button data-action="approve-commit">Finish</button>':run.status==='stopped'&&data.lease?.backend==='coder'&&attempt?.status==='merge_failed'?'<button data-action="retry-delivery">Retry delivery</button>':'')+
   (['awaiting_resume','paused_cooldown'].includes(run.status)?'<button data-action="resume">Continue</button>':'')+
   (['awaiting_dispatch','awaiting_commit','awaiting_review','awaiting_resume','paused_cooldown'].includes(run.status)?'<button class="secondary" data-action="discard">Close</button>':'')+'</div></section>';
 }
 if(!isActive&&data.task.status==='pending'&&data.blockers?.length)html+='<section class="run-notice warning"><div><strong>Cannot start yet</strong><p>'+data.blockers.map(esc).join(' ')+'</p></div><button id="configure-harnesses" class="secondary">Open settings</button></section>';
 if(!html&&!run)html='<section class="run-notice quiet"><span>Ready when you are. Send a message to run with new context, or choose Run to start as-is.</span></section>';
 $('#run-banner').innerHTML=html;
 document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>runAction(run.id,button.dataset.action));
 const connect=$('#connect-run-account');if(connect)connect.onclick=async()=>{await openCoderConnections(data.connection_action.server_id);await connectProvider(data.connection_action.server_id,data.connection_action.provider)};
 const setup=$('#configure-harnesses');if(setup)setup.onclick=openProjectSettings;
}
function conciseRunMessage(message){
 return String(message||'').replace(/Harness failed\.\s*/i,'The harness stopped. ').replace(/(?:Worktree|Files are) preserved at\s+[^.\n]+(?:\.|$)/gi,'Work is preserved for review.').replace(/Files remain at\s+[^.\n]+(?:\.|$)/gi,'Work is preserved for review.').replace(/\s{2,}/g,' ').trim();
}
function renderConversation(data){
 const priorOpen=new Set([...document.querySelectorAll('#conversation details[open][data-attempt]')].map(node=>node.dataset.attempt));
 const attempts=new Map(data.attempts.map(attempt=>[attempt.id,attempt]));const displayed=new Set();
 const runCard=attempt=>{
  displayed.add(attempt.id);const status=attemptStatus(attempt,data.attempts);const quota=attempt.status==='quota';return '<details class="run-card" data-attempt="'+attempt.id+'" '+(attempt.status==='running'?'open':'')+'><summary><span class="run-dot '+(quota?'quota':'')+'"></span><span>'+esc(harnessName(attempt.harness_key))+'</span><small><span data-progress-count="'+attempt.id+'">Activity recorded</span> · '+esc(status)+'</small></summary><div class="run-card-body"><div id="attempt-progress-'+attempt.id+'" class="harness-progress"><span class="muted">Loading completed work…</span></div>'+(attempt.display_reason||attempt.error?(quota?'<p class="muted">Work was preserved and the next harness can continue from it.</p>':'<p class="error">'+esc(attempt.display_reason||attempt.error)+'</p>'):'')+'<div class="run-links"><button class="secondary" data-attempt-detail="'+attempt.id+'">Run details</button><a href="/api/attempts/'+attempt.id+'/raw" download>Raw transcript</a></div></div></details>';
 };
 const user=message=>'<article class="message user"><div class="message-label">You</div><div class="message-content">'+renderChatText(message.content)+'</div></article>';
 const assistant=message=>'<article class="message assistant"><div class="message-label"><span class="harness-avatar">'+esc(harnessName(message.harness_key).slice(0,1))+'</span>'+esc(harnessName(message.harness_key))+(message.model&&message.model!=='default'?'<small>'+esc(message.model)+'</small>':'')+'</div><div class="message-content">'+renderChatText(message.content)+'</div></article>';
 let html='';for(const message of data.messages){
  const attempt=attempts.get(message.attempt_id);
  if(message.role==='user')html+=user(message);
  else if(message.role==='assistant'){if(attempt&&!displayed.has(attempt.id))html+=runCard(attempt);html+=assistant(message)}
  else if(attempt&&!displayed.has(attempt.id))html+=runCard(attempt);
 }
 for(const attempt of data.attempts)if(!displayed.has(attempt.id))html+=runCard(attempt);
 if(!html)html=user({content:data.task.text});$('#conversation').innerHTML=html;
 document.querySelectorAll('#conversation details[data-attempt]').forEach(node=>{node.open=priorOpen.has(node.dataset.attempt)||node.open});
 document.querySelectorAll('[data-attempt-detail]').forEach(button=>button.onclick=()=>attemptDetail(+button.dataset.attemptDetail));
}
function progressSteps(events){
 const seen=new Set(),steps=[];for(const event of events||[]){
  if(!['command','edit','tool','result','permission'].includes(event.kind))continue;
  const status=String(event.status||'').toLowerCase();const done=['completed','complete','success','succeeded'].includes(status);const active=['working','running','started','in_progress'].includes(status);const key=[event.kind,event.text,status].join('|');if(seen.has(key))continue;seen.add(key);
  const action=event.kind==='edit'?'Updated':event.kind==='command'?(done?'Ran':'Running'):event.kind==='permission'?'Needs permission':done?'Completed':'Using';steps.push({action,text:event.text||event.kind,status:done?'done':active?'active':status==='failed'?'attention':'done'});
 }
 return steps.slice(-12);
}
function renderAttemptProgress(attempt,data){
 const host=$('#attempt-progress-'+attempt.id);if(!host)return;const steps=progressSteps(data.events);const completed=steps.filter(step=>step.status==='done').length;const count=$('[data-progress-count="'+attempt.id+'"]');if(count)count.textContent=completed?completed+' step'+(completed===1?'':'s')+' complete':attempt.status==='running'?'Working now':'No structured steps';
 const replies=(state.sessionData?.messages||[]).filter(message=>message.attempt_id===attempt.id&&message.role==='assistant').map(message=>message.content.trim());
 const trace=(data.events||[]).length?'<section class="attempt-trace" aria-label="Harness reasoning and activity"><p class="trace-heading">Harness updates</p>'+renderHarnessEvents(data.events,replies,attempt.id)+'</section>':'<span class="muted">'+(attempt.status==='running'?'Waiting for the first visible step…':'No structured activity was recorded for this run.')+'</span>';
 host.innerHTML=trace;
}
async function hydrateHarnessProgress(session){
 await Promise.all(session.attempts.map(async attempt=>{try{const detail=await api('/api/attempts/'+attempt.id+'/log');if(state.taskId===session.task.id)renderAttemptProgress(attempt,detail)}catch(error){/* A missing log should not interrupt the conversation. */}}));
}
function renderActivity(data){
 const attempt=state.sessionData?.attempts.find(item=>item.id===state.sessionData?.run?.attempt_id);const steps=progressSteps(data.events);const reasoning=(data.events||[]).filter(event=>event.kind==='reasoning').slice(-3);$('#run-activity').hidden=false;
 $('#activity-summary').innerHTML='<div class="activity-heading"><strong>'+esc(attempt?harnessName(attempt.harness_key):'Harness')+' is working</strong><span>'+steps.filter(step=>step.status==='done').length+' completed step'+(steps.filter(step=>step.status==='done').length===1?'':'s')+'</span></div>'+(reasoning.length?'<section class="live-reasoning"><div class="reasoning-label">Latest reasoning summaries</div>'+reasoning.map(event=>'<div>'+renderChatText(event.text)+'</div>').join('')+'</section>':'')+(steps.length?steps.slice(-6).map(step=>'<div class="activity-event '+esc(step.status)+'"><span>'+esc(step.action)+'</span><div>'+esc(step.text)+'</div></div>').join(''):'<p class="muted">Waiting for the first visible step…</p>');
 if(attempt)renderAttemptProgress(attempt,data);
 $('#live-output').textContent=data.log||'';followLatest();
}
function renderNativeSession(data){const node=$('#native-session');if(!data?.resume_command){node.textContent='';return}node.innerHTML='<details><summary>Saved Codex CLI session</summary><code>'+esc(data.resume_command)+'</code></details>'}

function chatScroller(){const pane=$('.main-pane');return pane.scrollHeight>pane.clientHeight+2&&getComputedStyle(pane).overflowY==='auto'?pane:document.scrollingElement}
function followLatest(){if(state.followOutput===false){$('#jump-latest').hidden=false;return}$('#jump-latest').hidden=true;requestAnimationFrame(()=>{const scroller=chatScroller();scroller.scrollTop=scroller.scrollHeight})}
document.addEventListener('scroll',event=>{if(!state.taskId||event.target!==chatScroller())return;const scroller=chatScroller();state.followOutput=scroller.scrollHeight-scroller.scrollTop-scroller.clientHeight<100;$('#jump-latest').hidden=state.followOutput},true);
$('#jump-latest').onclick=()=>{state.followOutput=true;followLatest()};

async function runAction(id,action){if(action==='discard'&&!confirm('Close this run? Project files are left untouched.'))return;try{await api('/api/runs/'+id+'/'+action,'POST',{});state.sessionSnapshot=null;await load()}catch(error){toast(error.message)}}
async function attemptDetail(id){try{const data=await api('/api/attempts/'+id+'/log');$('#detail-kicker').textContent='HARNESS RUN';$('#detail-title').textContent='Run details';$('#detail-body').style.display='block';$('#detail-body').textContent=data.log||'No output recorded.';$('#detail-form').innerHTML='<button id="show-diff" class="secondary">View diff</button>';$('#show-diff').onclick=async()=>{try{const diff=await api('/api/attempts/'+id+'/diff');$('#detail-body').textContent=diff.diff||'No diff available.'}catch(error){toast(error.message)}};$('#detail').showModal()}catch(error){toast(error.message)}}

function openProjectSettings(){
 const project=current();if(!project)return;$('#detail-kicker').textContent='PROJECT SETTINGS';$('#detail-title').textContent=project.name;$('#detail-body').style.display='none';
 const profile=project.coder_profile||{},servers=state.data.coder_servers||[];
 const serverOptions='<option value="">No Coder server · local only</option>'+servers.map(server=>'<option value="'+server.id+'" '+(+profile.coder_server_id===server.id?'selected':'')+'>'+esc(server.name)+' · '+esc(server.status)+'</option>').join('');
 $('#detail-form').innerHTML='<form id="project-policy"><label>Project name<input name="name" value="'+esc(project.name)+'" required></label><label>Verify command<input name="verify_command" value="'+esc(project.verify_command)+'" required></label><label>Working location<select name="execution_mode"><option value="local" '+(project.execution_mode==='local'?'selected':'')+'>Project folder</option><option value="worktree" '+(project.execution_mode==='worktree'?'selected':'')+'>Isolated Git worktree</option></select></label><label>Run mode<select name="default_mode"><option value="supervised" '+(project.default_mode==='supervised'?'selected':'')+'>Ask before running and finishing</option><option value="unattended" '+(project.default_mode==='unattended'?'selected':'')+'>Run and finish automatically</option></select></label><label class="switch"><input name="auto_failover" type="checkbox" '+(project.auto_failover?'checked':'')+'> Automatically continue with the next harness after a limit</label><hr><div class="settings-title"><div><p class="eyebrow">CODER EXECUTION</p><h3>Project environment</h3><p class="muted">Select a reviewed Coder template for this project.</p></div><button id="manage-coder" class="secondary" type="button">Manage servers</button></div><label>Coder server<select name="coder_server_id">'+serverOptions+'</select></label><label>Coder template<input name="template_name" value="'+esc(profile.template_name||'')+'" placeholder="agent-template"></label><p class="dialog-help">Changing this does not alter an existing runner. Use Runner → Migrate to create a new private workspace and preserve the old one.</p><label>Project default<select name="default_target"><option value="local" '+(profile.default_target!=='coder'?'selected':'')+'>Local execution</option><option value="coder" '+(profile.default_target==='coder'?'selected':'')+'>Coder environment</option></select></label><label>Setup profile<select name="setup_profile"><option value="auto" '+(profile.setup_profile==='auto'?'selected':'')+'>Auto-detect project</option><option value="python" '+(profile.setup_profile==='python'?'selected':'')+'>Python</option><option value="node" '+(profile.setup_profile==='node'?'selected':'')+'>Node</option></select></label><label>Remote repository URL<input name="repo_url" value="'+esc(profile.repo_url||'')+'" placeholder="Uses origin when left blank"></label><label>Base branch<input name="base_ref" value="'+esc(profile.base_ref||'main')+'"></label><label>Repository connection ID<input name="auth_provider_id" value="'+esc(profile.auth_provider_id||'github')+'" placeholder="github"></label><p class="dialog-help">This is the provider ID configured on the selected Coder server, such as github or primary-gitlab.</p><button>Save project settings</button></form><hr><div class="settings-section"><div class="settings-title"><div><p class="eyebrow">HARNESS ROTATION</p><h3>Fallback order</h3><p class="muted">Only enabled harnesses are used. This order applies when a task has no specific preference.</p></div><button id="scan" class="secondary">Rescan</button></div><div id="settings-harnesses"></div></div>';
 $('#project-policy').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);try{await api('/api/projects/'+project.id,'POST',{name:form.get('name'),verify_command:form.get('verify_command'),execution_mode:form.get('execution_mode'),default_mode:form.get('default_mode'),auto_failover:form.has('auto_failover')?1:0});await api('/api/projects/'+project.id+'/coder-profile','POST',{coder_server_id:form.get('coder_server_id'),template_name:form.get('template_name'),default_target:form.get('default_target'),setup_profile:form.get('setup_profile'),repo_url:form.get('repo_url'),base_ref:form.get('base_ref'),auth_provider_id:form.get('auth_provider_id')});$('#detail').close();await load();toast('Project settings saved')}catch(error){toast(error.message)}};
 $('#manage-coder').onclick=openCoderServers;
 $('#scan').onclick=scanHarnesses;renderHarnessSettings();$('#detail').showModal();
}
function openCoderServers(){
 $('#detail-kicker').textContent='CODER SERVERS';$('#detail-title').textContent='Execution environments';$('#detail-body').style.display='none';
 const cards=(state.data.coder_servers||[]).map(server=>'<article class="harness-card"><div class="harness-top"><div><strong>'+esc(server.name)+'</strong><small>'+esc(server.base_url)+' · '+esc(server.status)+(server.version?' · '+esc(server.version):'')+'</small></div><div class="inline-actions"><button class="secondary" data-coder-connections="'+server.id+'">Connections</button><button class="secondary" data-model-auth="'+server.id+'">Models</button><button class="secondary" data-verify-coder="'+server.id+'">Verify</button></div></div><p>'+esc(server.detail||'Not checked yet.')+'</p><p class="dialog-help">Token: '+(server.token_configured?'stored in macOS Keychain':'not configured')+'</p></article>').join('')||'<p class="muted">No Coder servers registered. Find your local server or add one below.</p>';
 $('#detail-form').innerHTML='<div class="settings-section"><div class="settings-title"><div><p class="eyebrow">LOCAL DISCOVERY</p><h3>Find localhost Coder</h3><p class="muted">Checks only 127.0.0.1 and localhost on port 3000. It does not scan your network.</p></div><button id="discover-coder" class="secondary">Find local</button></div><div id="coder-discovery"></div></div><div class="settings-section"><p class="eyebrow">REGISTER SERVER</p><form id="coder-server-form"><label>Name<input name="name" placeholder="Hunter-local" required></label><label>Server URL<input name="base_url" placeholder="http://127.0.0.1:3000" required></label><label>Organization<input name="organization" value="default"></label><label>Coder API token <input name="token" type="password" autocomplete="off" placeholder="Stored in macOS Keychain"></label><p class="dialog-help">A token is needed to verify the account and later create templates/workspaces. It is never stored in the project database.</p><button>Add Coder server</button></form></div><hr><div class="settings-section">'+cards+'</div>';
 $('#coder-server-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);try{await api('/api/coder-servers','POST',Object.fromEntries(form));await load();openCoderServers();toast('Coder server registered')}catch(error){toast(error.message)}};
 $('#discover-coder').onclick=async()=>{const button=$('#discover-coder');button.disabled=true;try{const data=await api('/api/coder-servers/discover','POST',{});const host=$('#coder-discovery');host.innerHTML=data.servers.length?data.servers.map(server=>'<p class="muted">Found '+esc(server.base_url)+(server.version?' · '+esc(server.version):'')+' <button class="secondary" data-add-coder="'+esc(server.base_url)+'">Use</button></p>').join(''):'<p class="muted">No local Coder server responded.</p>';host.querySelectorAll('[data-add-coder]').forEach(item=>item.onclick=()=>{$('#coder-server-form [name=base_url]').value=item.dataset.addCoder;$('#coder-server-form [name=name]').value='Local Coder'});}catch(error){toast(error.message)}finally{button.disabled=false}};
 document.querySelectorAll('[data-verify-coder]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/coder-servers/'+button.dataset.verifyCoder+'/verify','POST',{});await load();openCoderServers();toast('Coder server checked')}catch(error){toast(error.message)}finally{button.disabled=false}});
 document.querySelectorAll('[data-coder-connections]').forEach(button=>button.onclick=()=>openCoderConnections(+button.dataset.coderConnections));
 document.querySelectorAll('[data-model-auth]').forEach(button=>button.onclick=()=>openModelConnections(+button.dataset.modelAuth));
 document.querySelectorAll('[data-coder-connections]').forEach(button=>{const runner=document.createElement('button');runner.className='secondary';runner.textContent='Runner';runner.onclick=()=>openCoderRunner(+button.dataset.coderConnections);button.parentElement.append(runner)});
 if(!$('#detail').open)$('#detail').showModal();
}
async function openModelConnections(serverId){
 $('#detail-kicker').textContent='RUNNER MODEL ACCOUNTS';$('#detail-title').textContent='Connect coding agents';$('#detail-body').style.display='none';if(!$('#detail').open)$('#detail').showModal();
 $('#detail-form').innerHTML='<p class="muted">Checking the persistent runner…</p>';
 try{
  const data=await api('/api/coder-servers/'+serverId+'/model-auth');const codex=data.providers.codex,claude=data.providers.claude;
  const state=provider=>provider.authenticated?'connected':'not connected';
  const codexFlow=codex.flow;
  const claudeFlow=claude.flow;
  const codexBody=codexFlow&&codexFlow.status==='pending'
   ?'<p>In your browser, open <a href="'+esc(codexFlow.verification_url)+'" target="_blank" rel="noopener noreferrer">OpenAI device sign-in</a> and enter:</p><p><code>'+esc(codexFlow.user_code)+'</code></p><p id="model-flow-status" class="dialog-help">'+esc(codexFlow.message)+'</p>'
   :'<p class="dialog-help">'+(codex.authenticated?'Connected'+(codex.email?' as '+esc(codex.email):'')+(codex.plan_type?' · '+esc(codex.plan_type):''):'Codex will keep its own managed ChatGPT login in this runner. Harness never stores that token.')+'</p><button id="connect-codex" '+(codex.authenticated?'disabled':'')+'>Connect Codex</button>';
  const claudeBody=claudeFlow&&claudeFlow.status==='pending'
   ?'<p class="dialog-help">Authorize Claude in your browser, then paste the one-time return code that Claude shows after approval. It is needed once to deliver the browser login to this remote runner; the resulting credential stays in the runner for future tasks.</p>'+(claudeFlow.verification_url?'<p><a class="button-link" href="'+esc(claudeFlow.verification_url)+'" target="_blank" rel="noopener noreferrer">1. Continue with Claude</a></p>':'<p class="dialog-help">Preparing secure Claude sign-in…</p>')+'<label>2. Paste Claude’s return code<input id="claude-login-input" autocomplete="one-time-code" placeholder="Paste the one-time code from Claude"></label><button id="send-claude-login">Finish connection</button><p id="claude-flow-status" class="dialog-help">'+esc(claudeFlow.message||'Waiting for Claude Code.')+'</p>'
   :'<p class="dialog-help">'+(claude.authenticated?'Connected'+(claude.email?' as '+esc(claude.email):''):'Claude Code uses its native login in the same persistent runner. Harness opens its native sign-in in this dialog and never stores its credential.')+'</p><button id="connect-claude" '+(claude.authenticated?'disabled':'')+'>Connect Claude Code</button>'+(claude.detail?'<p class="dialog-help">'+esc(claude.detail)+'</p>':'');
  $('#detail-form').innerHTML='<p>One private runner stores each CLI’s native, renewable login. Tasks reuse that runner, so they do not ask you to sign in again.</p><article class="harness-card"><div class="harness-top"><strong>Codex</strong><span class="connection-state '+(codex.authenticated?'connected':'')+'">'+state(codex)+'</span></div>'+codexBody+'</article><article class="harness-card"><div class="harness-top"><strong>Claude Code</strong><span class="connection-state '+(claude.authenticated?'connected':'')+'">'+state(claude)+'</span></div>'+claudeBody+'</article><button id="models-back" class="secondary">Back</button>';
  $('#models-back').onclick=openCoderServers;
  const connect=$('#connect-codex');if(connect)connect.onclick=async()=>{connect.disabled=true;try{await api('/api/coder-servers/'+serverId+'/model-auth/codex/connect','POST',{});await openModelConnections(serverId)}catch(error){toast(error.message);connect.disabled=false}};
  const connectClaude=$('#connect-claude');if(connectClaude)connectClaude.onclick=async()=>{connectClaude.disabled=true;try{await api('/api/coder-servers/'+serverId+'/model-auth/claude/connect','POST',{});await openModelConnections(serverId)}catch(error){toast(error.message);connectClaude.disabled=false}};
  const sendClaude=$('#send-claude-login');if(sendClaude)sendClaude.onclick=async()=>{const input=$('#claude-login-input');sendClaude.disabled=true;try{await api('/api/coder-servers/'+serverId+'/model-auth/claude/input','POST',{input:input.value});input.value='';await openModelConnections(serverId)}catch(error){toast(error.message);sendClaude.disabled=false}};
  if(codexFlow&&codexFlow.status==='pending'){const poll=async()=>{try{const fresh=await api('/api/coder-servers/'+serverId+'/model-auth');if(!$('#model-flow-status'))return;if(fresh.providers.codex.flow?.status==='pending'){setTimeout(poll,2500)}else await openModelConnections(serverId)}catch(error){const el=$('#model-flow-status');if(el)el.textContent=error.message}};setTimeout(poll,2500)}
  if(claudeFlow&&claudeFlow.status==='pending'){const poll=async()=>{try{const fresh=await api('/api/coder-servers/'+serverId+'/model-auth');if(!$('#claude-flow-status'))return;if(fresh.providers.claude.flow?.status==='pending'){setTimeout(poll,2500)}else await openModelConnections(serverId)}catch(error){const el=$('#claude-flow-status');if(el)el.textContent=error.message}};setTimeout(poll,2500)}
 }catch(error){$('#detail-form').innerHTML='<p class="error">'+esc(error.message)+'</p><button id="models-back">Back</button>';$('#models-back').onclick=openCoderServers}
}
async function openCoderConnections(serverId){
 if(!$('#detail').open)$('#detail').showModal();
 const server=(state.data.coder_servers||[]).find(item=>item.id===serverId);if(!server)return;$('#detail-kicker').textContent='CONNECTED ACCOUNTS';$('#detail-title').textContent=server.name;$('#detail-body').style.display='none';$('#detail-form').innerHTML='<p class="muted">Checking connections configured on this Coder server…</p>';
try{const data=await api('/api/coder-servers/'+serverId+'/external-auth');const providers=data.providers||[];$('#detail-form').innerHTML='<div class="settings-title"><div><p class="eyebrow">CODER CONNECTIONS</p><h3>Available providers</h3><p class="muted">Connections belong to your user on this Coder server. Projects select a provider by its ID.</p></div><button id="back-to-coder" class="secondary">Back</button></div>'+(providers.length?providers.map(connectionCard).join(''):'<p class="muted">This Coder deployment does not advertise any external-auth providers.</p>');$('#back-to-coder').onclick=openCoderServers;document.querySelectorAll('[data-connect-provider]').forEach(button=>button.onclick=()=>connectProvider(serverId,button.dataset.connectProvider));document.querySelectorAll('[data-refresh-connection]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const status=await api('/api/coder-servers/'+serverId+'/external-auth/'+button.dataset.refreshConnection);toast(status.authenticated?status.display_name+' is connected':status.display_name+' still needs to be connected');await openCoderConnections(serverId)}catch(error){toast(error.message)}finally{button.disabled=false}})}catch(error){$('#detail-form').innerHTML='<p class="muted">'+esc(error.message)+'</p><button id="back-to-coder" class="secondary">Back</button>';$('#back-to-coder').onclick=openCoderServers}
}
async function openCoderRunner(serverId){
 $('#detail-kicker').textContent='PERSISTENT RUNNER';$('#detail-title').textContent='Task execution environment';$('#detail-body').style.display='none';
 $('#detail-form').innerHTML='<p class="muted">Checking your Coder workspaces…</p>';if(!$('#detail').open)$('#detail').showModal();
 try{
  const data=await api('/api/coder-servers/'+serverId+'/runner');const runner=data.runner,project=current(),profile=project?.coder_profile;
  const migration=runner&&profile?.coder_server_id===serverId?'<hr><p><strong>Change runner template</strong></p><p class="dialog-help">Create a fresh private runner from <code>'+esc(profile.template_name)+'</code>. The current workspace, its worktrees, and native logins are preserved but Harness will use the new runner.</p><button id="migrate-runner" class="secondary">Migrate to '+esc(profile.template_name)+'</button>':'';
  const capacity=runner?.detected_max_tasks||1,cores=runner?.detected_cpu_count||'unknown',memory=runner?.detected_memory_bytes?Math.round(runner.detected_memory_bytes/1073741824)+' GiB':'unknown memory';
  $('#detail-form').innerHTML='<p>Tasks get separate Git worktrees on this private workspace. Native CLI logins stay in its persistent home directory; deleting the workspace or its storage can lose those logins.</p><p class="dialog-help">Remote capacity is automatic: <strong>'+esc(capacity)+' concurrent task'+(capacity===1?'':'s')+'</strong> from this runner’s '+esc(cores)+' CPU slot'+(cores===1?'':'s')+' and '+esc(memory)+'. It refreshes from the Coder workspace; there is no manual concurrency setting. Local project-folder tasks remain one at a time.</p><form id="runner-form"><label>Workspace<select name="workspace_name" required>'+data.workspaces.map(w=>'<option value="'+esc(w.name)+'" '+(runner?.workspace_id===w.id?'selected':'')+'>'+esc(w.name)+' · '+esc(w.status)+'</option>').join('')+'</select></label><p class="dialog-help">Each remote agent reserves 2 GiB of runner memory, so the displayed limit avoids memory overcommit.</p><button '+(!data.workspaces.length?'disabled':'')+'>Save runner</button></form>'+(runner?'<p>Saved runner: <a href="'+esc(runner.workspace_url)+'" target="_blank" rel="noopener noreferrer">'+esc(runner.workspace_name)+'</a>. Check model connection status in Models.</p>':'<p>No runner selected. Without a selection, the first remote task creates a persistent runner from the approved project template.</p>')+migration+'<button id="runner-back" class="secondary">Back</button>';
  $('#runner-back').onclick=openCoderServers;
  if(!runner){const select=$('#runner-form [name=workspace_name]');select.insertAdjacentHTML('afterbegin','<option value="">Choose a private runner workspace</option>');select.value=''}
  $('#runner-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);try{await api('/api/coder-servers/'+serverId+'/runner','POST',{workspace_name:form.get('workspace_name')});toast('Persistent runner saved and capacity measured');await openCoderRunner(serverId)}catch(error){toast(error.message)}};
  const migrate=$('#migrate-runner');if(migrate)migrate.onclick=async()=>{if(!confirm('Create a new runner from '+profile.template_name+'? The old workspace will not be deleted.'))return;migrate.disabled=true;try{const result=await api('/api/coder-servers/'+serverId+'/runner/migrate','POST',{project_id:project.id});await load();toast('New runner created; old '+(result.previous_workspace_name||'runner')+' was preserved.');await openCoderRunner(serverId)}catch(error){toast(error.message);migrate.disabled=false}};
 }catch(error){$('#detail-form').innerHTML='<p class="error">'+esc(error.message)+'</p><button id="runner-back">Back</button>';$('#runner-back').onclick=openCoderServers}
}
function connectionCard(provider){
 const github=provider.type==='github';
 const installUrl=provider.install_url||(github&&provider.provider==='github'?'https://github.com/apps/coder/installations/select_target':null);
 const help=github?'Identity authorization and GitHub App installation are separate. This card reports the app installation count; choose Manage repository access to review its selected repositories and permissions. Harness uses Coder’s workspace Git authentication for HTTPS delivery.':'';
return '<article class="harness-card"><div class="harness-top"><div><strong>'+esc(provider.display_name)+'</strong><small>'+esc(provider.type)+' · '+esc(provider.provider)+'</small></div><span class="connection-state '+(provider.authenticated?'connected':'')+'">'+(provider.authenticated?'Identity authorized':'Not authorized')+'</span></div>'+(help?'<p>'+esc(help)+'</p>':'')+'<div class="inline-actions"><button data-connect-provider="'+esc(provider.provider)+'">'+(provider.authenticated?'Reconnect account':'Connect to Coder')+'</button>'+(installUrl?'<a class="button-link secondary" href="'+esc(installUrl)+'" target="_blank" rel="noopener noreferrer">'+(provider.installation_count>0?'Manage repository access':'Install for repository access')+'</a>':'')+(!github?'<a class="button-link secondary" href="'+esc(provider.login_url)+'" target="_blank" rel="noopener noreferrer">Authorize account</a>':'')+'<button class="secondary" data-refresh-connection="'+esc(provider.provider)+'">Refresh status</button></div>'+(github?'<p>App installations reported: '+esc(provider.installation_count||0)+(provider.install_url?'':'. The installation link opens Coder’s built-in GitHub app; custom apps must be installed from their own page.')+'</p>':'')+'</article>';
}
async function connectProvider(serverId,provider){
 const base='/api/coder-servers/'+serverId+'/external-auth/'+encodeURIComponent(provider);
 try{
  const flow=await api(base+'/connect','POST',{});
  $('#detail-form').innerHTML='<h3>Finish connecting your account</h3><p>Copy this one-time code and enter it on the provider page:</p><p><code>'+esc(flow.user_code)+'</code></p><a class="button-link" href="'+esc(flow.verification_url)+'" target="_blank" rel="noopener noreferrer">Open authorization page</a><p id="device-flow-status">'+esc(flow.message)+'</p><p class="dialog-help">Harness completes the exchange for the registered Coder account. No separate Coder browser login is needed. Installation and repository permissions are checked separately.</p><button id="back-to-connections">Back to connections</button>';
  $('#back-to-connections').onclick=()=>openCoderConnections(serverId);
  const poll=async()=>{
   const node=$('#device-flow-status');if(!node)return;
   try{const state=await api(base+'/flow');if(!node.isConnected)return;node.textContent=state.message||state.status;if(state.status==='pending')setTimeout(poll,3000)}catch(error){node.textContent=error.message}
  };setTimeout(poll,3000);
 }catch(error){toast(error.message)}
}
function renderHarnessSettings(){
 const host=$('#settings-harnesses');if(!host)return;const pool=state.data.harnesses.filter(item=>item.enabled&&item.installed),others=state.data.harnesses.filter(item=>!item.enabled||!item.installed);
 const card=(harness,inPool,index)=>{const availability=harnessStatus(harness);return '<article class="harness-card"><div class="harness-top"><div><strong>'+esc(harness.label)+'</strong><small>'+esc(availability.label)+'</small></div><div class="inline-actions">'+(inPool?'<button class="icon-button" data-move="'+harness.key+'" data-step="-1" '+(index===0?'disabled':'')+' aria-label="Move up">↑</button><button class="icon-button" data-move="'+harness.key+'" data-step="1" '+(index===pool.length-1?'disabled':'')+' aria-label="Move down">↓</button>':'')+'<button class="secondary" data-pool="'+harness.key+'" data-include="'+(inPool?0:1)+'">'+(inPool?'Remove':'Add')+'</button></div></div><p>'+esc(availability.reason)+'</p>'+(inPool?'<label>Model<select data-model="'+harness.key+'">'+modelOptions(harness.key,harness.model)+'</select></label>':'')+permissionControl(harness)+'</article>'};
 host.innerHTML=(pool.length?pool.map((item,index)=>card(item,true,index)).join(''):'<p class="muted">No available harnesses in rotation. Rescan and add one.</p>')+(others.length?'<details><summary>Other harnesses ('+others.length+')</summary>'+others.map(item=>card(item,false,0)).join('')+'</details>':'');
 host.querySelectorAll('[data-move]').forEach(button=>button.onclick=()=>moveHarness(button.dataset.move,+button.dataset.step));host.querySelectorAll('[data-pool]').forEach(button=>button.onclick=()=>updateHarness(button.dataset.pool,{enabled:+button.dataset.include},true));host.querySelectorAll('[data-model]').forEach(select=>select.onchange=()=>updateHarness(select.dataset.model,{model:select.value}));host.querySelectorAll('[data-permissions]').forEach(select=>select.onchange=()=>updateHarness(select.dataset.permissions,{tool_permissions:select.value}));
}
async function scanHarnesses(){const button=$('#scan');button.disabled=true;button.textContent='Scanning…';try{await api('/api/scan','POST',{});await load();renderHarnessSettings();toast('Harnesses refreshed')}catch(error){toast(error.message)}finally{if(button){button.disabled=false;button.textContent='Rescan'}}}
async function updateHarness(key,body,refresh=false){try{await api('/api/harnesses/'+key,'POST',body);await load();if(refresh)renderHarnessSettings();toast('Rotation saved')}catch(error){toast(error.message)}}
async function moveHarness(key,step){const pool=state.data.harnesses.filter(item=>item.enabled&&item.installed).map(item=>item.key),index=pool.indexOf(key),target=index+step;if(target<0||target>=pool.length)return;[pool[index],pool[target]]=[pool[target],pool[index]];const order=[...pool,...state.data.harnesses.filter(item=>!pool.includes(item.key)).map(item=>item.key)];try{await api('/api/harness-order','POST',{order});await load();renderHarnessSettings()}catch(error){toast(error.message)}}

function openTaskSettings(){
 const task=taskById();if(!task)return;$('#detail-kicker').textContent='TASK SETTINGS';$('#detail-title').textContent=task.text;$('#detail-body').style.display='none';
 $('#detail-form').innerHTML='<form id="task-policy"><label>Chat name<input name="text" value="'+esc(task.text)+'" required></label><label>Execution target<select name="execution_target"><option value="project" '+(task.execution_target==='project'?'selected':'')+'>Use project default · '+esc(task.execution_target_label||'Local')+'</option><option value="local" '+(task.execution_target==='local'?'selected':'')+'>Local execution</option><option value="coder" '+(task.execution_target==='coder'?'selected':'')+'>Coder environment</option></select></label><p class="dialog-help">A Coder override uses this project’s connected server and generated template.</p><label>Preferred harness<select name="preferred_harness"><option value="">Use project rotation</option>'+state.data.harnesses.map(harness=>'<option value="'+harness.key+'" '+(harness.key===task.preferred_harness?'selected':'')+'>'+esc(harness.label)+'</option>').join('')+'</select></label><label>Preferred model<input name="preferred_model" value="'+esc(task.preferred_model||'')+'" placeholder="Harness default or model ID"></label><label>Run mode<select name="mode_override"><option value="">Use project default</option><option value="supervised" '+(task.mode_override==='supervised'?'selected':'')+'>Ask before running and finishing</option><option value="unattended" '+(task.mode_override==='unattended'?'selected':'')+'>Run and finish automatically</option></select></label><label class="switch"><input name="force_gate" type="checkbox" '+(task.force_gate?'checked':'')+'> Always ask before dispatching or finishing this task</label><button>Save task settings</button></form><hr><button id="delete-task" class="danger">Delete this chat</button>';
 $('#task-policy').insertAdjacentHTML('afterbegin',taskPermissionControl(task.tool_permissions));
 $('#task-policy').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);try{await api('/api/tasks/'+task.id,'POST',{text:form.get('text'),execution_target:form.get('execution_target'),tool_permissions:form.get('tool_permissions'),preferred_harness:form.get('preferred_harness')||null,preferred_model:form.get('preferred_model')||null,mode_override:form.get('mode_override')||null,force_gate:form.has('force_gate')?1:0});$('#detail').close();state.sessionSnapshot=null;await load();toast('Task settings saved')}catch(error){toast(error.message)}};
 $('#delete-task').onclick=()=>deleteTask(task.id);$('#detail').showModal();
}
async function renameTask(id=state.taskId){const task=taskById(id);if(!task)return;const name=prompt('Rename this chat',task.text);if(name===null||name.trim()===task.text)return;try{await api('/api/tasks/'+id,'POST',{text:name.trim()});state.sessionSnapshot=null;await load();toast('Chat renamed')}catch(error){toast(error.message)}}
async function deleteTask(id){const task=taskById(id);if(!task||!confirm('Delete “'+task.text+'”? This removes the chat and its saved run history.'))return;try{await api('/api/tasks/'+id,'DELETE');if(state.taskId===id)state.taskId=null;$('#detail').close();state.sessionSnapshot=null;await load();toast('Chat deleted')}catch(error){toast(error.message)}}
async function moveTask(projectId,taskId,step){const project=state.data.projects.find(item=>item.id===projectId),order=project.tasks.map(item=>item.id),index=order.indexOf(taskId),target=index+step;if(target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]];try{await api('/api/projects/'+projectId+'/task-order','POST',{order});await load();toast('Chat order saved')}catch(error){toast(error.message)}}

function openProjectForm(){$('#project-error').textContent='';$('#project-dialog').showModal()}
function newTask(){if(!current())return;$('#new-task-project').textContent=current().name;if(!$('#new-task [name=tool_permissions]'))$('#new-task').insertAdjacentHTML('afterbegin',taskPermissionControl('inherit'));$('#new-task-dialog').showModal()}
$('#new-goal').onclick=newTask;$('#add-project').onclick=openProjectForm;$('#welcome-add').onclick=()=>current()?newTask():openProjectForm();$('#workspace-settings').onclick=openProjectSettings;$('#goal-settings').onclick=openTaskSettings;
$('#run-session').onclick=async()=>{try{await api('/api/projects/'+state.projectId+'/run','POST',{task_id:state.taskId});state.sessionSnapshot=null;await load()}catch(error){$('#session-error').textContent=error.message}};
$('#session-message').onsubmit=async event=>{event.preventDefault();$('#session-error').textContent='';try{await api('/api/tasks/'+state.taskId+'/messages','POST',{content:$('#message-text').value,start:true});event.target.reset();state.sessionSnapshot=null;await load()}catch(error){$('#session-error').textContent=error.message}};
$('#new-task').onsubmit=async event=>{event.preventDefault();try{const task=await api('/api/projects/'+state.projectId+'/tasks','POST',{text:$('#new-task-text').value,tool_permissions:$('#new-task [name=tool_permissions]').value,start:false});event.target.reset();$('#new-task-dialog').close();state.taskId=task.id;state.sessionSnapshot=null;await load()}catch(error){toast(error.message)}};
$('#project-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);try{const project=await api('/api/projects','POST',{...Object.fromEntries(form),auto_failover:form.has('auto_failover')});state.projectId=project.id;state.taskId=null;$('#project-dialog').close();event.target.reset();await load()}catch(error){$('#project-error').textContent=error.message}};
async function browseFolder(path){$('#folder-error').textContent='';try{const folder=await api('/api/directories','POST',{path:path||null});state.folder=folder;$('#folder-path').value=folder.path;$('#folder-list').innerHTML=folder.folders.length?folder.folders.map((item,index)=>'<button type="button" data-folder="'+index+'">▸ '+esc(item.name)+'</button>').join(''):'<p class="muted">No subfolders. You can use this folder.</p>';document.querySelectorAll('[data-folder]').forEach(button=>button.onclick=()=>browseFolder(folder.folders[+button.dataset.folder].path));$('#folder-up').disabled=folder.parent===folder.path}catch(error){$('#folder-error').textContent=error.message}}
$('#choose-folder').onclick=()=>{$('#folder-dialog').showModal();browseFolder($('#project-form [name=repo_path]').value)};$('#folder-location').onsubmit=event=>{event.preventDefault();browseFolder($('#folder-path').value)};$('#folder-up').onclick=()=>browseFolder(state.folder?.parent);$('#use-folder').onclick=()=>{if(!state.folder)return;$('#project-form [name=repo_path]').value=state.folder.path;const name=$('#project-form [name=name]');if(!name.value)name.value=state.folder.name;$('#folder-dialog').close()};document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>$('#'+button.dataset.close).close());
load().catch(error=>toast(error.message));setInterval(()=>{if(!document.querySelector('dialog[open],input:focus,select:focus,textarea:focus'))load().catch(()=>{})},2500);

function permissionLabel(mode){return ({auto:'Auto permissions',standard:'Adapter defaults',ask:'Ask me',inherit:'Harness defaults'})[mode]||'Legacy permissions'}
function taskPermissionControl(value='inherit'){
 return '<label>Tool permissions<select name="tool_permissions">'+[['inherit','Use each harness’s default'],['auto','Auto · supported harness policy'],['standard','Use adapter defaults'],['ask','Ask me in chat · not available yet']].map(([key,label])=>'<option value="'+key+'" '+(key===value?'selected':'')+' '+(key==='ask'?'disabled':'')+'>'+label+'</option>').join('')+'</select></label><p class="dialog-help">Applies to the next run and its handoffs, independently of model and run/finish approval. Auto uses Codex review, Claude review, or Droid medium autonomy. OpenCode auto is unsupported and stops before execution. Live Allow / Deny in chat is not available yet.</p>';
}
function permissionControl(harness){
 const description={codex:'Default and Auto: workspace-write sandbox with automatic approval review.',claude:'Default: accept edits; other tools may be denied. Auto: Claude reviews requests automatically, subject to CLI/model support.',droid:'Default and Auto: medium autonomy for development, builds and dependency installation; not a filesystem sandbox.',opencode:'Default: your OpenCode permission configuration. Automatic review is not supported; existing CLI rules may already allow tools.'}[harness.key];
 return '<label>Default tool permissions<select data-permissions="'+harness.key+'"><option value="standard" '+(harness.tool_permissions!=='auto'?'selected':'')+'>Adapter default</option><option value="auto" '+(harness.tool_permissions==='auto'?'selected':'')+' '+(harness.key==='opencode'?'disabled':'')+'>Auto'+(harness.key==='opencode'?' · unsupported':'')+'</option><option disabled>Ask me in chat · unavailable</option></select></label><p class="dialog-help">'+description+' Applies to future runs using harness defaults. No permission bypass is enabled.</p>';
}
